import sys
from pathlib import Path

# add bench/ to path so the real module can be imported
bench_dir = Path(__file__).resolve().parent / "bench"
if str(bench_dir) not in sys.path:
    sys.path.insert(0, str(bench_dir))

from cdsfl_registry.composer import _count_constraints

policy = {
    "constraints": {
        "anti_deference": {
            "agreement_requires_evidence": True,
            "min_independent_observations": 1,
        },
        "convergence": {
            "hard_coverage_threshold": 1.0,
