        "sympy_sandbox": True,
    },
    "protocol": {
        "max_rounds": 5,
    },
}

count = _count_constraints(policy)

def deep_count(d):
    c = 0
    for v in d.values():
        if isinstance(v, dict):
            c += deep_count(v)
        elif isinstance(v, bool) and v:
            c += 1
        elif isinstance(v, str):
            c += 1
        elif v is not None and v is not False:
            c += 1
    return c

expected = (
    deep_count(policy.get("constraints", {})) +
    deep_count(policy.get("verification", {})) +
    deep_count(policy.get("protocol", {}))
)

if count < expected:
    raise AssertionError(
        f"FALSIFIED: undercount {count} vs correct {expected}"
    )
